      i = r.exports = a(0)(!0), i.push([r.i, ".uploader{position:relative}", "", { version: 3, sources: ["/Users/didi/Documents/git/private/vue-uploader/src/components/uploader.vue"], names: [], mappings: "AACA,UACE,iBAAmB,CACpB", file: "uploader.vue", sourcesContent: [`
.uploader {
  position: relative;
}
`], sourceRoot: "" }]);
